// ---------------------------------------------------------------------------
// WF7 · Construir el email AL CLIENTE (D39): presupuesto, visita confirmada o
// recordatorio. Plantilla fija: ningún LLM toca este texto, la cifra ni la
// fecha (D39.3, Adenda 1.1a). Todo dato variable pasa por esc() (G4).
// Entrada ($json): la respuesta COMPLETA de GET /oportunidades/{id}/ficha,
//   { statusCode, headers, body }, o, sin conexión, un dato SIN statusCode
//   (llega por la salida de error de leer_ficha).
// Lee además: el disparador (oportunidad_id, tipo, mensaje_cliente) y
//   leer_reglas (get_business_rules por MCP: "qué suele incluir").
// Salida: { enviar, para, asunto, html, motivo, aviso_tecnico,
//           mensaje_tecnico, oportunidad_id, tipo }
// Mode: Run Once for Each Item.
// ---------------------------------------------------------------------------

// ---- 1. Datos de partida ----------------------------------------------------
const entrada = $('When Executed by Another Workflow').first().json; // lo que pidió quien llama
const tipo = entrada.tipo;                                   // presupuesto | visita_confirmada | recordatorio
const op = entrada.oportunidad_id;                           // número de oportunidad
const mensajeCliente = String(entrada.mensaje_cliente ?? '').trim(); // texto opcional del formulario (D39.4)
const estado = $json.statusCode;                             // undefined si no hubo conexión
const f = $json.body ?? {};                                  // la ficha (o vacío)

// ---- 2. Datos fijos de la empresa (D39.6) ------------------------------------
const EMPRESA = 'Reformas Integrales Amedida';               // nombre comercial
const TELEFONO = '950 000 000';                              // teléfono de contacto (ficticio)
const EMAIL_EMPRESA = 'admin@example.com';      // email de administración (se sanea al exportar)
const DIRECCION = 'Calle de la Reforma, 12 · 04001 Almería'; // dirección postal ficticia

// ---- 3. Colores (los mismos que WF2 y la ficha) ------------------------------
const AZUL = '#0B3C5D';            // cabecera y títulos
const TURQUESA = '#1F8A8A';        // acentos y franjas
const TURQUESA_CLARO = '#E3F2F1';  // fondo de las cajas destacadas
const FONDO = '#EEF3F6';           // gris azulado alrededor de la tarjeta
const TEXTO = '#1F2933';           // texto principal
const SUAVE = '#5B6B79';           // texto secundario

// ---- 4. Escapar texto antes de meterlo en HTML (G4) -------------------------
// Nombre, mensaje y "qué incluye" vienen de personas o de la base de datos:
// esc() cambia los 5 caracteres especiales de HTML por su forma inofensiva.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ---- 5. Salida "no enviar" (G3, G5) ------------------------------------------
// tecnico = true -> el flujo avisa a WF4; false -> se calla (no es un fallo).
// El mensaje técnico NUNCA lleva datos del cliente.
function noEnviar(motivo, tecnico, mensajeTecnico) {
  return { json: { enviar: false, motivo, aviso_tecnico: tecnico,
                   mensaje_tecnico: mensajeTecnico, oportunidad_id: op, tipo } };
}

// ---- 6. Comprobaciones antes de escribir nada --------------------------------
// Tipo desconocido: error de quien llama (un flujo mal configurado).
if (!['presupuesto', 'visita_confirmada', 'recordatorio'].includes(tipo)) {
  return noEnviar('tipo_desconocido', true, `WF7 llamado con un tipo no previsto: ${tipo}`);
}
// Sin código HTTP: no hubo conexión con el backend.
if (estado === undefined) {
  return noEnviar('sin_conexion', true, `Sin conexión con el backend al leer la ficha (email ${tipo})`);
}
// Cualquier respuesta distinta de 200 es técnica (un 404 aquí es un id mal pasado).
if (estado !== 200) {
  return noEnviar('ficha_no_leida', true, `GET /ficha respondió ${estado} (email ${tipo})`);
}
// Lead antiguo sin contacto o sin email: no se envía y NO es un fallo (G3).
const c = f.contacto ?? {};
if (c.origen !== 'solicitud' || !c.email) {
  return noEnviar('sin_contacto', false, '');
}

// ---- 7. Formatos españoles (solo para MOSTRAR) --------------------------------
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }); // igual que el chat
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });            // "12" o "8,5"
// Fecha larga en hora de Madrid: "martes, 27 de octubre de 2026".
function diaLargo(t) {
  return new Date(t).toLocaleDateString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
}
// Hora en hora de Madrid: "10:00".
function hora(t) {
  return new Date(t).toLocaleTimeString('es-ES', {
    timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
}
// Fecha corta para el asunto: "27/10".
function diaCorto(t) {
  return new Date(t).toLocaleDateString('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit' });
}

// ---- 8. Diccionarios: códigos del backend -> texto para el cliente ----------
const TIPOS = { bano: 'baño', cocina: 'cocina', integral_vivienda: 'reforma integral de la vivienda',
  parcial_acabados: 'trabajos generales (pintura, electricidad o fontanería)' };
const ACABADOS = { basico: 'Básico', medio: 'Medio', alto: 'Alto' };
const r = f.reforma ?? {};                                   // tipo, m2, acabados, cambios
const tipoTexto = TIPOS[r.tipo_reforma] ?? 'reforma';         // si falta, una palabra neutra
// Solo el primer nombre en el saludo: menos datos personales en pantalla.
const nombre = String(c.nombre ?? '').trim().split(/\s+/)[0] || '';

// ---- 9. Piezas de HTML reutilizables ----------------------------------------
// Fila "etiqueta | valor": el VALOR siempre pasa por esc().
function fila(etiqueta, valor) {
  return `<tr><td style="padding:6px 0;width:42%;color:${SUAVE};font-size:13px;vertical-align:top;">${etiqueta}</td>` +
         `<td style="padding:6px 0;color:${TEXTO};font-size:14px;font-weight:bold;">${esc(valor)}</td></tr>`;
}
// Sección con título turquesa y contenido ya construido.
function seccion(titulo, contenido) {
  return `<tr><td style="padding:18px 32px 4px;">` +
    `<div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;color:${TURQUESA};font-weight:bold;` +
    `border-bottom:2px solid ${TURQUESA_CLARO};padding-bottom:6px;margin-bottom:6px;">${titulo}</div>${contenido}</td></tr>`;
}
// Párrafo normal (el texto ya debe venir escapado si es variable).
function parrafo(html) {
  return `<p style="font-size:14px;line-height:1.55;margin:8px 0;color:${TEXTO};">${html}</p>`;
}
// Caja destacada (cifra o cita): título pequeño y texto grande.
function caja(titulo, grande) {
  return `<tr><td style="padding:16px 32px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" ` +
    `style="background:${TURQUESA_CLARO};border-left:4px solid ${TURQUESA};border-radius:6px;"><tr><td style="padding:14px 18px;">` +
    `<div style="font-size:12px;color:${SUAVE};">${titulo}</div>` +
    `<div style="font-size:22px;font-weight:bold;color:${AZUL};margin-top:4px;">${grande}</div></td></tr></table></td></tr>`;
}
// Email completo: tarjeta blanca de 600 px, cabecera azul, contenido y pie con
// los datos de la empresa (D39.6) y por qué recibe el email.
function email(titulo, cuerpo, motivoPie) {
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"></head>` +
    `<body style="margin:0;padding:0;background:${FONDO};">` +
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${FONDO};padding:24px 0;"><tr><td align="center">` +
    `<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#FFFFFF;` +
    `border-radius:8px;font-family:Arial,Helvetica,sans-serif;color:${TEXTO};">` +
    `<tr><td style="background:${AZUL};padding:20px 32px;border-radius:8px 8px 0 0;color:#FFFFFF;font-size:18px;font-weight:bold;">${EMPRESA}</td></tr>` +
    `<tr><td style="height:4px;line-height:4px;font-size:0;background:${TURQUESA};">&nbsp;</td></tr>` +
    `<tr><td style="padding:24px 32px 0;"><div style="font-size:20px;font-weight:bold;color:${AZUL};">${titulo}</div></td></tr>` +
    cuerpo +
    `<tr><td style="padding:24px 32px;"><div style="border-top:1px solid #E5E9ED;padding-top:12px;font-size:12px;line-height:1.5;color:${SUAVE};">` +
    `${EMPRESA} · ${DIRECCION}<br>Tel. ${TELEFONO} · ${EMAIL_EMPRESA}<br>${motivoPie}</div></td></tr>` +
    `</table></td></tr></table></body></html>`;
}
// Saludo con el primer nombre (escapado) o sin él.
const saludo = nombre ? `Hola, ${esc(nombre)}:` : 'Hola:';

// ---- 10. Email 1: presupuesto (solo sin Gate, G1) ----------------------------
if (tipo === 'presupuesto') {
  const p = f.presupuesto;                                   // null si no hay presupuesto
  if (!p) {                                                  // se llama DESPUÉS de calcular: falta = fallo
    return noEnviar('sin_presupuesto', true, 'WF7 presupuesto llamado sin presupuesto calculado');
  }
  if (p.requiere_aprobacion !== false) {                     // G1: con Gate NUNCA cifra (D18.5.1)
    return noEnviar('con_gate', true, 'WF7 presupuesto llamado para un caso con Gate: NO se envía');
  }
  // "Qué suele incluir": la fila de get_business_rules de este tipo y nivel.
  // El MCP Client entrega la respuesta en content[0].text, como objeto o como
  // texto JSON (comprobado en el chat, D17.1): se aceptan las dos formas.
  let incluye = null;
  try {
    const bruto = $('leer_reglas').first().json.content?.[0]?.text;      // respuesta de la tool
    const reglas = typeof bruto === 'string' ? JSON.parse(bruto) : bruto; // texto -> objeto
    const filaReglas = (reglas?.incluye_tipico ?? []).find(
      (x) => x.tipo_reforma === r.tipo_reforma && x.nivel_acabados === r.nivel_acabados);
    incluye = filaReglas?.incluye_tipico ?? null;                         // null si no hay fila
  } catch (e) {
    incluye = null;                         // sin reglas: el email sale sin esa sección
  }
  const cuerpo =
    `<tr><td style="padding:8px 32px 0;">${parrafo(saludo)}` +
    parrafo('Gracias por contarnos tu proyecto. Esta es la estimación orientativa que te mostramos en el chat.') +
    `</td></tr>` +
    caja('Estimación orientativa (IVA incluido)',
         `${esc(eur.format(Number(p.importe_min_con_iva)))} – ${esc(eur.format(Number(p.importe_max_con_iva)))}`) +
    seccion('Lo que nos contaste', `<table role="presentation" width="100%" cellpadding="0" cellspacing="0">` +
      fila('Tipo de reforma', tipoTexto.charAt(0).toUpperCase() + tipoTexto.slice(1)) +
      fila('Superficie', `${num.format(Number(r.m2))} m²`) +
      fila('Nivel de acabados', ACABADOS[r.nivel_acabados] ?? '—') + `</table>`) +
    // D39.9: "Qué incluye tu estimación" = el alcance para el que se calculó la
    // cifra (no "suele incluir", que no convence; tampoco una promesa cerrada:
    // la frase siguiente dice que el técnico lo ajusta en la visita).
    (incluye ? seccion('Qué incluye tu estimación',
      parrafo(esc(incluye)) +
      parrafo('En la visita, el técnico lo ajusta a lo que necesitas de verdad.')) : '') +
    // D39.10: la visita contada como una ayuda, solo con lo que la empresa hace.
    seccion('El siguiente paso: tu visita técnica gratuita', parrafo(
      'El presupuesto definitivo se cierra tras una <b>visita técnica gratuita y sin compromiso</b>. ' +
      `Un técnico verá tu ${esc(tipoTexto)} en persona, te enseñará nuestro catálogo de acabados y las combinaciones ` +
      'posibles, y te explicará cada opción con detalle para que decidas con toda la información.') +
      parrafo(`Para pedirla, responde a este email o llámanos al ${TELEFONO}.`));
  return { json: { enviar: true, para: c.email, oportunidad_id: op, tipo, motivo: null,
    aviso_tecnico: false, mensaje_tecnico: '',
    asunto: `Tu estimación orientativa · ${tipoTexto.charAt(0).toUpperCase() + tipoTexto.slice(1)}`,
    html: email('Tu estimación orientativa', cuerpo,
      'Recibes este email porque pediste una estimación en nuestro chat.') } };
}

// ---- 11. Emails 2 y 3: visita confirmada y recordatorio ----------------------
// La visita CONFIRMADA de la oportunidad (como mucho hay una activa).
const v = (f.visitas ?? []).find((x) => x.estado_visita === 'confirmada');
if (!v) {                                    // se llama al confirmar: si no hay, es un fallo
  return noEnviar('sin_visita_confirmada', true, `WF7 ${tipo} llamado sin visita confirmada`);
}
const conGate = f.presupuesto?.requiere_aprobacion === true; // con Gate: nunca cifra (no se lee)
const cita = `${esc(diaLargo(v.fecha_visita))}, a las ${esc(hora(v.fecha_visita))}`;
// Nota de administración (D39.4): solo en la confirmación y solo si se escribió.
const nota = (tipo === 'visita_confirmada' && mensajeCliente)
  ? seccion('Nota de nuestro equipo', parrafo(esc(mensajeCliente).replace(/\r?\n/g, '<br>')))
  : '';
// D39.10: lo que el técnico hace en la visita, en viñetas (solo lo que la
// empresa hace de verdad). Cambios estructurales: una viñeta más, solo si los hay.
const estructura = r.incluye_cambios_estructurales === true
  ? '• Comprobará la viabilidad de los cambios en tabiques o estructura que nos comentaste.<br>'
  : '';
const despues = conGate
  ? 'Con todo lo que vea, preparará tu presupuesto.'
  : 'Con todo lo que vea, preparará el presupuesto definitivo, que sustituye a la estimación orientativa.';
const vinetas =
  `• Tomará medidas y revisará el estado actual de tu ${esc(tipoTexto)}.<br>` +
  estructura +
  '• Te enseñará nuestro catálogo de acabados y las combinaciones posibles.<br>' +
  '• Te explicará cada opción con detalle y resolverá todas tus dudas, sin compromiso.';
const cuerpoVisita =
  `<tr><td style="padding:8px 32px 0;">${parrafo(saludo)}` +
  parrafo(tipo === 'visita_confirmada'
    ? 'Tu visita técnica gratuita está confirmada.'
    : 'Te recordamos tu visita técnica gratuita.') + `</td></tr>` +
  caja('Visita técnica', cita) +
  nota +
  seccion('Qué hará el técnico por ti', parrafo(
    `Irá a la dirección que nos indicaste y te dedicará el tiempo que necesites:<br>${vinetas}`) +
    parrafo(despues)) +
  seccion('¿Necesitas cambiarla?', parrafo(
    `Llámanos al ${TELEFONO} o responde a este email y buscamos otro hueco.`));
const asunto = tipo === 'visita_confirmada'
  ? `Visita técnica confirmada · ${diaCorto(v.fecha_visita)} a las ${hora(v.fecha_visita)}`
  : `Recordatorio de tu visita técnica · ${diaCorto(v.fecha_visita)} a las ${hora(v.fecha_visita)}`;
return { json: { enviar: true, para: c.email, oportunidad_id: op, tipo, motivo: null,
  aviso_tecnico: false, mensaje_tecnico: '', asunto,
  html: email(tipo === 'visita_confirmada' ? 'Visita técnica confirmada' : 'Recordatorio de tu visita',
    cuerpoVisita, 'Recibes este email porque tienes una visita técnica con nosotros.') } };
